import numpy as np
from scipy import stats
from sklearn.cluster import SpectralClustering
from sklearn.metrics.pairwise import cosine_similarity

MAX_DRIVERS = 4

def design(feats):
    # Identify highly significant features (p < 0.01)
    sig_features = [fid for i, fid in enumerate(feats.ids) 
                    if feats.types[i] != 'derived' and abs(stats.ttest_ind(feats.x[:, feats.column(fid)], feats.y)[0]) > 3.0]

    if not sig_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Find correlated pairs with |r| >= 0.6
    corr_pairs = []
    for i, fid1 in enumerate(sig_features):
        for j, fid2 in enumerate(sig_features[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]) >= 0.6:
                corr_pairs.append((fid1, fid2))

    # If we have correlated pairs, cluster them to find modules
    if corr_pairs:
        # Build adjacency matrix
        nodes = set()
        for a, b in corr_pairs:
            nodes.add(a)
            nodes.add(b)

        if len(nodes) > 1:
            # Create similarity matrix for clustering
            node_list = sorted(list(nodes))
            n_nodes = len(node_list)
            sim_matrix = np.zeros((n_nodes, n_nodes))

            # Fill in correlation similarities
            for i, fid1 in enumerate(node_list):
                for j, fid2 in enumerate(node_list):
                    if i == j:
                        sim_matrix[i,j] = 1.0
                    else:
                        idx1 = feats.column(fid1)
                        idx2 = feats.column(fid2)
                        corr = np.corrcoef(feats.x[:, idx1], feats.x[:, idx2])[0,1]
                        sim_matrix[i,j] = max(0, corr)  # Use positive correlations

            # Cluster using spectral clustering
            clustering = SpectralClustering(n_clusters=min(3, max(1, n_nodes//2)), 
                                          affinity='precomputed', random_state=0)
            clusters = clustering.fit_predict(sim_matrix)

            # Get the largest cluster as our module
            unique_clusters, counts = np.unique(clusters, return_counts=True)
            main_cluster = unique_clusters[np.argmax(counts)]
            module_members = [node_list[i] for i in range(n_nodes) if clusters[i] == main_cluster]

            if len(module_members) > 1:
                # Compute weighted score based on mean differences
                loadings = {}
                for fid in module_members:
                    col_idx = feats.column(fid)
                    mean_diff = np.mean(feats.x[feats.y==1, col_idx]) - np.mean(feats.x[feats.y==0, col_idx])
                    loadings[fid] = mean_diff

                # Normalize loadings
                norm = np.sqrt(sum(v**2 for v in loadings.values()))
                if norm > 0:
                    loadings = {k: v/norm for k, v in loadings.items()}

                # Drivers are top 4 by effect size
                drivers = sorted(loadings.keys(), key=lambda x: abs(loadings[x]), reverse=True)[:MAX_DRIVERS]

                return Design(
                    drivers=tuple(drivers),
                    columns=tuple(module_members),
                    products=(),
                    loadings=loadings
                )

    # No strong module found, use top features directly
    drivers = [fid for i, fid in enumerate(feats.ids) 
               if feats.types[i] != 'derived' and abs(stats.ttest_ind(feats.x[:, feats.column(fid)], feats.y)[0]) > 3.0]

    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top 4 drivers by t-statistic
    drivers = sorted(drivers, key=lambda fid: abs(stats.ttest_ind(feats.x[:, feats.column(fid)], feats.y)[0]), reverse=True)
    drivers = drivers[:MAX_DRIVERS]

    # Simple weighted score
    loadings = {}
    for fid in drivers:
        col_idx = feats.column(fid)
        mean_diff = np.mean(feats.x[feats.y==1, col_idx]) - np.mean(feats.x[feats.y==0, col_idx])
        loadings[fid] = mean_diff

    # Normalize
    norm = np.sqrt(sum(v**2 for v in loadings.values()))
    if norm > 0:
        loadings = {k: v/norm for k, v in loadings.items()}

    return Design(
        drivers=tuple(drivers),
        columns=tuple(drivers),
        products=(),
        loadings=loadings
    )

